const docs='https://docs.crewai.com/v1.15.22/en/';
const source=(path,label='Documentación de CrewAI')=>'<a href="'+docs+path+'" target="_blank" rel="noopener noreferrer">'+label+'</a>';
const end=(idea,links='')=>'<div class="slide-end"><p class="takeaway">'+idea+'</p>'+(links?'<p class="source">'+links+'</p>':'')+'</div>';
const steps=(items)=>'<div class="pipeline">'+items.map((x,i)=>'<div class="pipe-step"><span class="step-number">'+(i+1)+'</span><h3>'+x[0]+'</h3><p>'+x[1]+'</p></div>'+(i<items.length-1?'<span class="pipe-arrow" aria-hidden="true">'+iconArrow+'</span>':'')).join('')+'</div>';
const code=(text)=>'<pre><code>'+text.replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;')+'</code></pre>';
function makeSlides(){return [
{title:'Un problema, varias responsabilidades',chapter:'La idea',render:()=>'<h2>“Hazme un informe<br>sobre <span class="accent">IA en educación</span>.”</h2><p class="lead">Una petición corta puede esconder mucho trabajo.</p>'+steps([['Investigar','Encontrar información y registrar de dónde viene.'],['Redactar','Organizar los hallazgos para una audiencia concreta.'],['Revisar','Detectar vacíos, comprobar citas y mejorar la claridad.']])+end('La primera decisión es cómo dividir el trabajo.')},
{title:'Modelo, agente y orquestación',chapter:'La idea',render:()=>'<h2>¿Dónde entra CrewAI?</h2><div class="layers"><div class="layer"><span class="layer-label">Modelo · LLM</span><div><h3>Genera y transforma lenguaje.</h3><p>Recibe contexto y produce una respuesta.</p></div></div><div class="layer"><span class="layer-label">Agente · Agent</span><div><h3>Trabaja hacia un objetivo.</h3><p>Combina el modelo con instrucciones y herramientas disponibles.</p></div></div><div class="layer active-layer"><span class="layer-label">CrewAI</span><div><h3>Organiza la colaboración.</h3><p>Framework de Python para coordinar agentes, tareas y flujos de trabajo.</p></div></div></div>'+end('CrewAI organiza el trabajo; el LLM aporta la generación de lenguaje.',source('concepts/agents','Agentes'))},
{title:'Cinco piezas para entender una Crew',chapter:'Las piezas',render:()=>'<h2>Un equipo se diseña<br>con <span class="accent">cinco piezas.</span></h2><div class="parts"><div><h3>¿Quién?</h3><span class="part-word">Agent</span><p>El responsable.</p></div><div><h3>¿Qué?</h3><span class="part-word">Task</span><p>El encargo y su entrega.</p></div><div><h3>¿Con qué?</h3><span class="part-word">Tool</span><p>Las acciones disponibles.</p></div><div><h3>¿En qué orden?</h3><span class="part-word">Process</span><p>La coordinación.</p></div><div class="crew-part"><h3>¿Qué equipo?</h3><span class="part-word">Crew</span><p>Las piezas reunidas.</p></div></div>'+end('Primero define las responsabilidades; después escribe el código.',source('concepts/crews','Crews'))},
{title:'Agent: una responsabilidad clara',chapter:'Las piezas',render:()=>'<h2>Un agente necesita<br>un encargo <span class="accent">bien definido.</span></h2><div class="split content-split"><dl class="definitions"><div><dt>role</dt><dd>Su función: investigador.</dd></div><div><dt>goal</dt><dd>La meta que debe alcanzar.</dd></div><div><dt>backstory</dt><dd>Contexto y enfoque para trabajar.</dd></div><div><dt>llm · tools</dt><dd>Modelo y capacidades disponibles.</dd></div></dl><div class="example-sheet"><h3>“Encuentra evidencia sobre IA en educación.”</h3><div class="sheet-heading">Responsabilidad del investigador</div><p>Prioriza fuentes primarias. Separa los resultados comprobados de las opiniones.</p><p class="small-note">El rol orienta al modelo; no certifica que sea experto.</p></div></div>'+end('El mismo modelo puede alimentar agentes con funciones distintas.',source('concepts/agents','Agent'))},
{title:'Task: definir qué significa terminar',chapter:'Las piezas',render:()=>'<h2>Una buena tarea dice<br><span class="accent">qué entregar.</span></h2><div class="task-contrast"><div class="vague"><span class="comparison-label">Encargo ambiguo</span><p>“Investiga IA en educación.”</p><span>No define alcance ni criterio de entrega.</span></div><div class="specific"><span class="comparison-label">Encargo verificable</span><p>“Compara 3 usos educativos.<br>Para cada uno: beneficio, limitación y fuente.”</p><span><code>expected_output</code>: tabla con 3 filas y enlaces.</span></div></div><div class="inline-terms"><span><code>description</code> El trabajo</span><span><code>agent</code> El responsable</span><span><code>context</code> Las entradas previas</span></div>'+end('Una salida esperada precisa ayuda a evaluar; no garantiza exactitud.',source('concepts/tasks','Task'))},
{title:'Tools: conectar el modelo con acciones',chapter:'Las piezas',render:()=>'<h2>El modelo propone.<br>La herramienta <span class="accent">actúa.</span></h2><div class="tool-diagram"><div class="tool-agent"><h3>“Necesito<br>una fuente.”</h3><span>Solicitud del agente</span></div><div class="tool-link">'+iconArrow+'<span>Llamada</span></div><div class="tool-functions"><div><b>Buscar</b><span>Consultar una API.</span></div><div><b>Leer</b><span>Recuperar un documento.</span></div><div><b>Calcular</b><span>Ejecutar una función.</span></div></div><div class="tool-link">'+iconArrow+'<span>Resultado</span></div><div class="tool-result"><h3>Datos para<br>continuar.</h3></div></div><p class="lead compact">Una herramienta puede ser una función Python expuesta con <code>@tool</code>. Sus permisos y validaciones los define quien construye el sistema.</p>'+end('Sin una herramienta de búsqueda, el agente no navega por sí solo.',source('concepts/tools','Tools'))},
{title:'Crew: conectar las entregas',chapter:'El equipo en acción',render:()=>'<h2>La salida de uno<br>es el contexto del siguiente.</h2><div class="handoffs"><div class="handoff"><span>Investigador</span><div class="document-shape"><b>Evidencia</b><i></i><i></i><i></i></div><p>Hallazgos + fuentes</p></div><div class="transfer">'+iconArrow+'<code>context</code></div><div class="handoff"><span>Redactor</span><div class="document-shape"><b>Borrador</b><i></i><i></i><i></i></div><p>Una explicación ordenada</p></div><div class="transfer">'+iconArrow+'<code>context</code></div><div class="handoff"><span>Editor</span><div class="document-shape final-document"><b>Informe</b><i></i><i></i><i></i></div><p>Versión revisada</p></div></div>'+end('La Crew reúne los agentes, sus tareas y el proceso de ejecución.',source('concepts/crews','Crews')+' · '+source('concepts/tasks','Contexto'))},
{title:'Dos formas de coordinar',chapter:'El equipo en acción',render:()=>'<h2>¿El orden está claro<br>o alguien debe coordinar?</h2><div class="processes"><div><h3>Secuencial</h3><p>Las tareas siguen el orden definido.</p><div class="mini-sequence"><span>Investigar</span>'+iconArrow+'<span>Redactar</span>'+iconArrow+'<span>Revisar</span></div><code>Process.sequential</code><p class="small-note">Útil para un recorrido predecible.</p></div><div><h3>Jerárquico</h3><p>Un manager asigna y revisa el trabajo.</p><div class="hierarchy"><b>Manager</b><div><span>Investigador</span><span>Redactor</span></div></div><code>Process.hierarchical</code><p class="small-note">Requiere <code>manager_llm</code> o <code>manager_agent</code>.</p></div></div>'+end('Más coordinación también puede añadir llamadas, tiempo y costo.',source('concepts/processes','Procesos'))},
{title:'Sigamos un informe de principio a fin',chapter:'El equipo en acción',render:()=>'<h2>Así viaja el trabajo.</h2><p class="lead compact">Objetivo: explicar los usos de IA en educación a un grupo de TI.</p><div class="simulation"><div class="sim-steps" role="group" aria-label="Etapas del ejemplo"><button class="sim-step selected" data-step="0" aria-pressed="true"><span>1</span>Investigar</button><button class="sim-step" data-step="1" aria-pressed="false"><span>2</span>Redactar</button><button class="sim-step" data-step="2" aria-pressed="false"><span>3</span>Revisar</button></div><div id="sim-output" class="sim-output" aria-live="polite"></div></div><div class="demo-footer"><span class="caption">Ejemplo ilustrativo · No ejecuta agentes ni consulta una API.</span><button class="action" id="step-example">Siguiente etapa '+iconArrow+'</button></div>'+end('Cada entrega debe conservar la evidencia que necesita la siguiente.')},
{title:'La estructura en Python',chapter:'El equipo en acción',render:()=>'<h2>Las piezas se unen así.</h2><div class="split code-split"><div>'+code('from crewai import Crew, Process\n\nequipo = Crew(\n    agents=[investigador, redactor, editor],\n    tasks=[investigar, redactar, revisar],\n    process=Process.sequential\n)\n\nresultado = equipo.kickoff(\n    inputs={"tema": "IA en educación"}\n)')+'<p class="caption">Fragmento conceptual: supone agentes, tareas y modelo ya configurados.</p></div><div class="code-notes"><div><b>agents</b><p>Quiénes integran el equipo.</p></div><div><b>tasks</b><p>Qué trabajos se ejecutan.</p></div><div><b>kickoff()</b><p>Inicia la ejecución con las entradas.</p></div></div></div>'+end('Los nombres en el código corresponden a las piezas que ya conoces.',source('concepts/crews','Crews'))},
{title:'Contexto, memoria y conocimiento',chapter:'Más allá de lo básico',render:()=>'<h2>Dar información no siempre<br>significa lo mismo.</h2><div class="knowledge-rows"><div><h3>Contexto</h3><p>Lo que esta tarea necesita ahora.</p><span>El redactor recibe la investigación.</span></div><div><h3>Memoria</h3><p>Información guardada para recuperarla después.</p><span>Una preferencia recordada: escribir para principiantes.</span></div><div><h3>Conocimiento</h3><p>Material de referencia aportado al sistema.</p><span>Un manual, un PDF o documentos del curso.</span></div></div><p class="small-note">La documentación consultada describe una memoria unificada. Conviene revisar la versión antes de configurar su almacenamiento.</p>'+end('Recordar un dato no lo convierte en verdadero.',source('concepts/memory','Memoria')+' · '+source('concepts/knowledge','Conocimiento'))},
{title:'Flows: controlar el recorrido completo',chapter:'Más allá de lo básico',render:()=>'<h2>La Crew hace el trabajo.<br>El Flow controla <span class="accent">el recorrido.</span></h2><div class="flow-map"><div class="flow-node">Recibir tema</div><div class="flow-line">'+iconArrow+'</div><div class="flow-node highlighted">Ejecutar Crew</div><div class="flow-line">'+iconArrow+'</div><div class="flow-node">Validar salida</div><div class="flow-branches"><div><span>Cumple</span><b>Entregar</b></div><div><span>Falta evidencia</span><b>Volver a investigar</b></div></div></div><p class="lead compact">Un Flow combina pasos de Python, eventos y estado. Puede decidir rutas, conectar Crews y gestionar reintentos.</p>'+end('La autonomía puede vivir dentro de un proceso controlado.',source('concepts/flows','Flows'))},
{title:'CrewAI dentro del ecosistema',chapter:'Criterio de diseño',render:()=>'<h2>Distintas formas de pensar<br>la orquestación.</h2><div class="framework-table"><div class="table-header"><span>Herramienta</span><span>Idea central</span></div><div class="featured"><b>CrewAI</b><span>Roles, tareas, equipos y Flows.</span></div><div><b>LangGraph</b><span>Grafos de ejecución con estado.</span></div><div><b>AutoGen</b><span>Agentes que colaboran mediante mensajes.</span></div><div><b>ChatDev</b><span>Colaboración multiagente; su versión 2 amplía el foco original en software.</span></div></div><p class="small-note">Comparación conceptual, sin ranking de “mejor”. LangChain y LangGraph son herramientas relacionadas, con niveles de abstracción distintos.</p>'+end('Elige según el control y la estructura que requiere tu problema.','<a href="https://reference.langchain.com/python/langgraph/overview" target="_blank" rel="noopener noreferrer">LangGraph</a> · <a href="https://www.microsoft.com/en-us/research/project/autogen/" target="_blank" rel="noopener noreferrer">AutoGen</a> · <a href="https://github.com/OpenBMB/ChatDev" target="_blank" rel="noopener noreferrer">ChatDev</a>')},
{title:'Cuándo tiene sentido un equipo',chapter:'Criterio de diseño',render:()=>'<h2>Más agentes <span class="accent">no siempre</span><br>significa mejor.</h2><div class="decision-columns"><div><h3>Puede ayudar cuando…</h3><ul><li>Hay responsabilidades claramente separables.</li><li>Se necesitan herramientas o fuentes distintas.</li><li>El trabajo exige varias entregas y revisiones.</li></ul></div><div><h3>Empieza más simple si…</h3><ul><li>Una llamada al modelo resuelve la tarea.</li><li>Las reglas son deterministas: basta un script.</li><li>La coordinación cuesta más que el beneficio.</li></ul></div></div>'+end('Ejemplos en TI: informes técnicos, análisis de incidencias y documentación.')},
{title:'Autonomía con límites',chapter:'Criterio de diseño',render:()=>'<h2>Coordinar no elimina<br>los errores.</h2><div class="risk-rows"><div><b>Información falsa</b><span>Exigir fuentes y contrastar las afirmaciones.</span></div><div><b>Costo y latencia</b><span>Medir llamadas, tiempo y presupuesto.</span></div><div><b>Bucles y delegación</b><span>Acotar iteraciones y responsabilidades.</span></div><div><b>Acciones y datos</b><span>Limitar permisos y revisar acciones sensibles.</span></div></div><p class="small-note"><code>verbose=True</code> muestra registros de ejecución. No garantiza acceso al razonamiento interno del modelo.</p>'+end('Evalúa el resultado con criterios externos al propio equipo.',source('concepts/agents','Límites y registros'))},
{title:'¿Cómo lo diseñarías tú?',chapter:'Para cerrar',render:()=>'<div class="discussion"><h2>Una universidad quiere<br>comparar tres plataformas<br>de <span class="accent">bases de datos.</span></h2><p class="lead">¿Qué agentes crearías y qué debería entregar cada uno?</p><div class="question-prompts"><span>¿Quién investiga?</span><span>¿Qué evidencia entrega?</span><span>¿Quién valida?</span></div><button class="action" id="reveal" aria-expanded="false" aria-controls="answer">Mostrar una propuesta '+iconArrow+'</button><div id="answer" hidden><p><b>Investigador:</b> recopila funciones y fuentes oficiales.<br><b>Analista:</b> compara con criterios acordados.<br><b>Revisor:</b> comprueba que cada conclusión tenga evidencia.</p><span class="caption">Un proceso secuencial es un punto de partida; no es la única solución.</span></div></div>'},
{title:'Diseña el equipo, no solo el prompt',chapter:'Para cerrar',render:()=>'<div class="closing"><h2>Diseña el equipo.<br>Define la entrega.<br><span class="accent">Comprueba el resultado.</span></h2><p class="lead">CrewAI conecta responsabilidades, herramientas y procesos.<br>La calidad sigue necesitando criterio humano.</p><div class="closing-bottom"><div class="recap"><span>Agent</span><span>Task</span><span>Tool</span><span>Process</span><span>Crew</span></div><button class="quiet" data-slide="0">Volver al inicio '+iconArrow+'</button></div><details class="references"><summary>Fuentes y lecturas conceptuales</summary><p>Contenido adaptado de GUIA_CREWAI.md y contrastado con documentación oficial el 24 de septiembre de 2026.</p><div>'+source('concepts/agents','Agentes')+' · '+source('concepts/tasks','Tareas')+' · '+source('concepts/crews','Crews')+' · '+source('concepts/tools','Herramientas')+' · '+source('concepts/processes','Procesos')+' · '+source('concepts/memory','Memoria')+' · '+source('concepts/knowledge','Conocimiento')+' · '+source('concepts/flows','Flows')+'</div><p>Las opciones pueden cambiar entre versiones. Los ejemplos de esta presentación son conceptuales.</p></details></div>'}
];}
const exampleStages=[
{heading:'Entrega del investigador',body:'Tres temas para explorar: tutoría, retroalimentación y apoyo docente.',artifact:'Hallazgos + enlaces a fuentes',detail:'Cada afirmación debe acompañarse de evidencia. Este ejemplo describe la estructura; no presenta hallazgos reales.'},
{heading:'Entrega del redactor',body:'Convierte la evidencia en una explicación: qué hace la IA, dónde ayuda y qué límites tiene.',artifact:'Borrador para estudiantes de TI',detail:'Recibe los hallazgos como contexto y conserva las referencias al desarrollar cada sección.'},
{heading:'Entrega del editor',body:'Comprueba que las conclusiones estén respaldadas y que el informe sea comprensible.',artifact:'reporte_final.md',detail:'Si una afirmación no tiene fuente, debe marcarla para revisión. El resultado todavía requiere validación humana.'}
];let exampleStep=0;
function showExample(n){exampleStep=n;const d=exampleStages[n];const output=document.getElementById('sim-output');if(!output)return;output.innerHTML='<h3>'+d.heading+'</h3><span class="artifact-label">'+d.artifact+'</span><p>'+d.body+'</p><span class="small-note">'+d.detail+'</span>';document.querySelectorAll('.sim-step').forEach((b,i)=>{b.classList.toggle('selected',i===n);b.setAttribute('aria-pressed',String(i===n))});document.getElementById('step-example').innerHTML=(n===2?'Reiniciar ejemplo':'Siguiente etapa')+iconArrow;}
document.addEventListener('click',e=>{const step=e.target.closest('[data-step]');if(step)showExample(Number(step.dataset.step));if(e.target.closest('#step-example'))showExample((exampleStep+1)%3);if(e.target.closest('#reveal')){const b=document.getElementById('reveal'),answer=document.getElementById('answer');answer.hidden=!answer.hidden;b.setAttribute('aria-expanded',String(!answer.hidden));b.innerHTML=(answer.hidden?'Mostrar una propuesta':'Ocultar propuesta')+iconArrow;}});

